// A deliberately bounded, verified-TLS reader for one approved public Hub endpoint.
// It is a real net/http client, not an API mock or a general-purpose HTTP proxy.
package main

import (
	"bytes"
	"context"
	"crypto/sha256"
	"crypto/tls"
	"crypto/x509"
	"encoding/hex"
	"encoding/json"
	"errors"
	"flag"
	"fmt"
	"io"
	"net"
	"net/http"
	"net/url"
	"os"
	"strconv"
	"strings"
	"time"
)

const approvedHost = "hub.docker.com"
const approvedPath = "/v2/repositories/library/busybox/tags"
const approvedURL = "https://hub.docker.com/v2/repositories/library/busybox/tags?page_size=100"
const pageBytes = 2 * 1024 * 1024
const totalBytes = 8 * 1024 * 1024

type HTTPRecord struct {
	URL string `json:"url"`
	Started string `json:"started_utc"`
	Finished string `json:"finished_utc"`
	Status int `json:"status_code"`
	StatusText string `json:"status"`
	Protocol string `json:"protocol"`
	Headers http.Header `json:"headers"`
	Body []byte `json:"body_base64"`
	BodySHA256 string `json:"body_sha256"`
	BodyTruncated bool `json:"body_truncated"`
	TLSVersion uint16 `json:"tls_version"`
	CipherSuite uint16 `json:"cipher_suite"`
	VerifiedChains [][]string `json:"verified_chain_der_sha256"`
	Error string `json:"error,omitempty"`
}
type PageRecord struct {
	URL string `json:"url"`
	Count int64 `json:"count"`
	Names []string `json:"names"`
	Next *string `json:"next"`
	FetchedUTC string `json:"fetched_utc"`
}
type TagRecord struct {
	Name string `json:"name"`
	Digest string `json:"digest,omitempty"`
	LastUpdated string `json:"last_updated,omitempty"`
	Images []struct {
		Architecture string `json:"architecture"`
		OS string `json:"os"`
		Digest string `json:"digest"`
	} `json:"images"`
}
type Report struct {
	Started string `json:"started_utc"`
	Finished string `json:"finished_utc"`
	InitialURL string `json:"initial_url"`
	CAPath string `json:"ca_path"`
	CAHash string `json:"ca_sha256"`
	BinaryHash string `json:"binary_sha256"`
	TLSVerification bool `json:"tls_verification_enabled"`
	Limits map[string]int `json:"limits"`
	HTTP []HTTPRecord `json:"http"`
	Pages []PageRecord `json:"pages"`
	Tags []TagRecord `json:"tags"`
	WireBytes int `json:"wire_bytes_stored"`
	UniqueNames int `json:"unique_names"`
	Complete bool `json:"complete"`
	Consistency string `json:"consistency"`
	Error string `json:"error,omitempty"`
}

func hash(data []byte) string { h := sha256.Sum256(data); return hex.EncodeToString(h[:]) }
func approved(raw string) (*url.URL, int, error) {
	u, err := url.Parse(raw)
	if err != nil { return nil, 0, err }
	if u.Scheme != "https" || !strings.EqualFold(u.Hostname(), approvedHost) || (u.Port() != "" && u.Port() != "443") || u.User != nil || u.Fragment != "" {
		return nil, 0, errors.New("only approved hub.docker.com HTTPS:443 without userinfo or fragment is allowed")
	}
	if strings.TrimSuffix(u.Path, "/") != approvedPath || u.RawPath != "" || u.EscapedPath() != u.Path {
		return nil, 0, errors.New("only the exact approved public BusyBox tag-list path is allowed")
	}
	q, err := url.ParseQuery(u.RawQuery)
	if err != nil { return nil, 0, err }
	for key, values := range q {
		if (key != "page" && key != "page_size") || len(values) != 1 { return nil, 0, errors.New("unapproved or duplicate query parameter") }
	}
	if q.Get("page_size") != "100" { return nil, 0, errors.New("page_size must be exactly 100") }
	page := 1
	if text := q.Get("page"); text != "" {
		page, err = strconv.Atoi(text)
		if err != nil || page < 1 || page > 8 { return nil, 0, errors.New("page is outside the approved 1..8 bound") }
	}
	u.Host = approvedHost
	return u, page, nil
}

func fetch(ctx context.Context, client *http.Client, raw string, expectedPage int, report *Report) ([]byte, string, error) {
	current := raw
	for redirects := 0; redirects <= 2; redirects++ {
		u, page, err := approved(current)
		if err != nil || page != expectedPage {
			if err == nil { err = errors.New("redirect changed the expected page") }
			return nil, "", err
		}
		if len(report.HTTP) >= 24 { return nil, "", errors.New("HTTP request bound exceeded") }
		record := HTTPRecord{URL:u.String(), Started:time.Now().UTC().Format(time.RFC3339Nano)}
		req, err := http.NewRequestWithContext(ctx, http.MethodGet, u.String(), nil)
		if err != nil { return nil, "", err }
		req.Header.Set("Accept", "application/json")
		req.Header.Set("Accept-Encoding", "identity")
		req.Header.Set("Cache-Control", "no-cache")
		req.Header.Set("User-Agent", "OpsForge-session06-bounded-verified-TLS-reader/1")
		response, err := client.Do(req)
		if err != nil {
			record.Error = err.Error(); record.Finished = time.Now().UTC().Format(time.RFC3339Nano)
			report.HTTP = append(report.HTTP, record)
			return nil, "", err
		}
		record.Status, record.StatusText, record.Protocol = response.StatusCode, response.Status, response.Proto
		record.Headers = response.Header.Clone()
		if response.TLS == nil || !response.TLS.HandshakeComplete || len(response.TLS.VerifiedChains) == 0 {
			response.Body.Close(); return nil, "", errors.New("verified TLS chain is required")
		}
		record.TLSVersion, record.CipherSuite = response.TLS.Version, response.TLS.CipherSuite
		for _, chain := range response.TLS.VerifiedChains {
			var fingerprints []string
			for _, certificate := range chain { fingerprints = append(fingerprints, hash(certificate.Raw)) }
			record.VerifiedChains = append(record.VerifiedChains, fingerprints)
		}
		remaining := totalBytes - report.WireBytes
		limit := pageBytes
		if remaining < limit { limit = remaining }
		if limit <= 0 { response.Body.Close(); return nil, "", errors.New("total response byte bound exhausted") }
		body, readErr := io.ReadAll(io.LimitReader(response.Body, int64(limit+1)))
		response.Body.Close()
		if len(body) > limit { body = body[:limit]; record.BodyTruncated = true }
		record.Body, record.BodySHA256 = body, hash(body)
		record.Finished = time.Now().UTC().Format(time.RFC3339Nano)
		if readErr != nil { record.Error = readErr.Error() }
		report.WireBytes += len(body); report.HTTP = append(report.HTTP, record)
		if readErr != nil { return nil, "", readErr }
		if record.BodyTruncated { return nil, "", errors.New("response byte limit reached; result is incomplete") }
		if response.StatusCode >= 300 && response.StatusCode <= 399 {
			if redirects == 2 { return nil, "", errors.New("same-domain redirect bound exceeded") }
			location, err := response.Location()
			if err != nil { return nil, "", err }
			if _, nextPage, err := approved(location.String()); err != nil || nextPage != expectedPage {
				return nil, "", errors.New("redirect is outside the approved host/path/page boundary")
			}
			current = location.String(); continue
		}
		if response.StatusCode == 401 || response.StatusCode == 403 { return nil, "", errors.New("authorization failure is not an empty tag list") }
		if response.StatusCode != http.StatusOK { return nil, "", fmt.Errorf("Hub returned HTTP %d, not a complete tag page", response.StatusCode) }
		if coding := response.Header.Get("Content-Encoding"); coding != "" && coding != "identity" { return nil, "", errors.New("unexpected compressed response; raw bytes retained but not treated as JSON") }
		return body, u.String(), nil
	}
	return nil, "", errors.New("redirect limit exceeded")
}

func enumerate(ctx context.Context, client *http.Client, raw string, maximum int, report *Report) error {
	seenNames, seenURLs := map[string]bool{}, map[string]bool{}
	current, expectedPage, expectedCount := raw, 1, int64(-1)
	for pageIndex := 0; pageIndex < maximum; pageIndex++ {
		u, page, err := approved(current)
		if err != nil { return err }
		if page != expectedPage || seenURLs[u.String()] { return errors.New("non-sequential or repeated next URL") }
		seenURLs[u.String()] = true
		body, actualURL, err := fetch(ctx, client, u.String(), expectedPage, report)
		if err != nil { return err }
		var pageBody struct { Count json.Number `json:"count"`; Next *string `json:"next"`; Results []TagRecord `json:"results"` }
		decoder := json.NewDecoder(bytes.NewReader(body)); decoder.UseNumber()
		if err := decoder.Decode(&pageBody); err != nil { return fmt.Errorf("invalid Hub JSON page: %w", err) }
		var extra any
		if decoder.Decode(&extra) != io.EOF { return errors.New("extra content after Hub JSON object") }
		count, err := pageBody.Count.Int64()
		if err != nil || count < 0 || len(pageBody.Results) > 100 { return errors.New("invalid Hub count/results shape") }
		if expectedCount < 0 { expectedCount = count }
		if count != expectedCount { return errors.New("Hub count changed while paging; cannot claim a complete snapshot") }
		pageRecord := PageRecord{URL:actualURL, Count:count, Next:pageBody.Next, FetchedUTC:time.Now().UTC().Format(time.RFC3339Nano)}
		for _, tag := range pageBody.Results {
			if tag.Name == "" || len(tag.Name) > 256 || seenNames[tag.Name] { return errors.New("missing/duplicate tag name while paging; result is incomplete") }
			seenNames[tag.Name] = true; pageRecord.Names = append(pageRecord.Names, tag.Name); report.Tags = append(report.Tags, tag)
		}
		report.Pages = append(report.Pages, pageRecord); report.UniqueNames = len(seenNames)
		if pageBody.Next == nil {
			if int64(len(seenNames)) != expectedCount { return errors.New("terminal page does not reconcile with the observed count") }
			report.Complete = true
			report.Consistency = "next exhausted with stable counts and unique names; mutable Hub pages are observations, not an atomic immutable snapshot"
			return nil
		}
		if *pageBody.Next == "" { return errors.New("empty non-null next is not a terminal page") }
		if _, nextPage, err := approved(*pageBody.Next); err != nil || nextPage != expectedPage+1 { return errors.New("next URL violates approved host/path/sequential page boundary") }
		current = *pageBody.Next; expectedPage++
	}
	return errors.New("page limit reached with non-null next; enumeration is incomplete")
}

func main() {
	flags := flag.NewFlagSet("hub-tls-client", flag.ContinueOnError)
	flags.SetOutput(io.Discard)
	initial := flags.String("url", approvedURL, "fixed approved public Hub URL")
	caPath := flags.String("ca", "/tools/ca-certificates.crt", "explicit CA bundle")
	caExpected := flags.String("ca-sha256", "", "required trusted CA bundle SHA256")
	maximum := flags.Int("max-pages", 8, "bounded page count 1..8")
	report := Report{Started:time.Now().UTC().Format(time.RFC3339Nano), InitialURL:*initial, TLSVerification:true,
		Limits:map[string]int{"pages":8,"page_bytes":pageBytes,"total_body_bytes":totalBytes,"http_requests":24,"same_page_redirects":2,"overall_seconds":60,"request_seconds":30,"limit_probe_extra_bytes":1}}
	var runErr error
	if err := flags.Parse(os.Args[1:]); err != nil { runErr = err }
	report.InitialURL, report.CAPath = *initial, *caPath
	if runErr == nil && (*maximum < 1 || *maximum > 8 || flags.NArg() != 0) { runErr = errors.New("invalid bounded argument set") }
	if runErr == nil { _, _, runErr = approved(*initial) }
	var pool *x509.CertPool
	if runErr == nil {
		data, err := os.ReadFile(*caPath)
		if err != nil { runErr = err } else {
			report.CAHash = hash(data)
			if len(*caExpected) != 64 || report.CAHash != *caExpected { runErr = errors.New("CA bundle hash does not match trusted profile") } else {
				pool = x509.NewCertPool()
				if !pool.AppendCertsFromPEM(data) { runErr = errors.New("explicit CA bundle contains no usable certificates") }
			}
		}
	}
	if executable, err := os.Executable(); err == nil {
		if data, err := os.ReadFile(executable); err == nil { report.BinaryHash = hash(data) }
	}
	if runErr == nil {
		transport := &http.Transport{Proxy:nil, TLSClientConfig:&tls.Config{RootCAs:pool, MinVersion:tls.VersionTLS12},
			DialContext:(&net.Dialer{Timeout:8*time.Second, KeepAlive:15*time.Second}).DialContext,
			TLSHandshakeTimeout:10*time.Second, ResponseHeaderTimeout:15*time.Second, IdleConnTimeout:15*time.Second,
			MaxIdleConns:2, MaxIdleConnsPerHost:2, DisableCompression:true, ForceAttemptHTTP2:true}
		client := &http.Client{Transport:transport, Timeout:30*time.Second, CheckRedirect:func(*http.Request, []*http.Request) error { return http.ErrUseLastResponse }}
		ctx, cancel := context.WithTimeout(context.Background(), 60*time.Second)
		runErr = enumerate(ctx, client, *initial, *maximum, &report)
		cancel(); transport.CloseIdleConnections()
	}
	if runErr != nil { report.Error = runErr.Error(); report.Complete = false }
	report.Finished = time.Now().UTC().Format(time.RFC3339Nano)
	encoder := json.NewEncoder(os.Stdout); encoder.SetEscapeHTML(false)
	if err := encoder.Encode(report); err != nil { os.Exit(2) }
	if runErr != nil { os.Exit(1) }
}
